import { useEffect, useMemo, useState, type CSSProperties } from 'react';
import { BookOpen, Crown } from 'lucide-react';
import type { Player } from '@/types/player';
import { cn } from '@/lib/utils';
import { matchPlayerByName } from '@/utils/leagueContent';
import { getTeamColors, getTeamTextColor } from '@/utils/teamColors';
import SectionIntro from './SectionIntro';
import TeamLogo from '../brand/TeamLogo';
import './recordboard.css';

// The in-game record board (the coach's club only) beside the same records across the whole league
// (public/data/league/records.json, generated by scripts/league_records.py). Compact tiles in the holder's club colours.

interface Entry { value: number; mark: string; player: string; name?: string; pos?: string; team?: string; season?: string; club?: boolean }
interface BoardRow {
  record: string;
  short: string;
  scope: 'career' | 'season' | 'game' | 'other';
  club: { mark: string; value: number | null; holder: string; year: string; name?: string; team?: string };
  league: { value: number; mark: string; top: Entry[]; basis: string; clubHolds: boolean } | null;
  broken?: boolean;
}
interface BoardFile { seasonsFrom: string | null; seasonsTo: string | null; records: BoardRow[] }

let cache: Promise<BoardFile | null> | null = null;
const loadBoard = () =>
  (cache ??= fetch(`${import.meta.env.BASE_URL}data/league/records.json`)
    .then((r) => (r.ok ? (r.json() as Promise<BoardFile>) : null))
    .catch(() => null));

/** A club's colours as CSS vars for a tile or a name: --t1/--t2 (HSL triplets), --ink (readable text). */
const clubVars = (team?: string | null): CSSProperties => {
  const c = getTeamColors(team);
  return c ? ({ '--t1': c.primary, '--t2': c.secondary, '--ink': getTeamTextColor(team) ?? 'hsl(var(--chalk))' } as CSSProperties) : {};
};

const display = (e: Entry) => e.name ?? e.player.replace(/^[A-Z]{1,2} /, '');

const Name = ({ e, players, onSelect }: { e: Entry; players: Player[]; onSelect: (p: Player) => void }) => {
  const p = matchPlayerByName(display(e), players);
  const body = (
    <>
      {e.team && <TeamLogo team={e.team} size={14} decorative />}
      <span className="rb-name__text">{display(e)}</span>
      {e.season && <span className="rb-name__yr">{e.season}</span>}
    </>
  );
  return p ? (
    <button type="button" className="rb-name" style={clubVars(e.team)} onClick={() => onSelect(p)} aria-label={`Open ${p.name}'s card`}>
      {body}
    </button>
  ) : (
    <span className="rb-name" style={clubVars(e.team)}>{body}</span>
  );
};

const Tile = ({ r, players, onSelect, open, onToggle }: { r: BoardRow; players: Player[]; onSelect: (p: Player) => void; open: boolean; onToggle: () => void }) => {
  const L = r.league!;
  const lead = L.top[0];
  const clubEntry: Entry = { value: r.club.value ?? 0, mark: r.club.mark, player: r.club.holder, name: r.club.name, team: r.club.team, season: r.club.year, club: true };
  // the gauge: how close the club's mark comes to the league's, or the nearest challenger to the club's record
  const rival = L.clubHolds ? L.top.find((e) => !e.club) : clubEntry;
  const pct = rival && L.value ? Math.max(4, Math.min(100, (rival.value / L.value) * 100)) : 0;
  return (
    <li className={cn('rb-tile', r.broken && 'rb-tile--broken', open && 'rb-tile--open')} style={clubVars(lead.team)}>
      <button type="button" className="rb-tile__face" onClick={onToggle} aria-expanded={open} aria-label={`${r.record}: ${L.mark} by ${display(lead)}. ${open ? 'Hide' : 'Show'} the top three`}>
        <span className="rb-tile__top">
          <span className="rb-tile__kicker">{r.short}</span>
          {r.broken ? <span className="rb-tile__flag">Beaten</span> : <Crown className="rb-tile__crown" aria-hidden="true" />}
        </span>
        <span className="rb-tile__mark">{L.mark}</span>
        <span className="rb-tile__holder">
          {lead.team && <TeamLogo team={lead.team} size={16} decorative backed />}
          <span className="rb-tile__holder-name">{display(lead)}</span>
          {lead.season && <span className="rb-tile__yr">{lead.season}</span>}
        </span>
        {rival && (
          <span className="rb-gauge" aria-hidden="true">
            <span className="rb-gauge__fill" style={{ width: `${pct}%`, ...clubVars(rival.team) }} />
          </span>
        )}
        <span className="rb-tile__foot">
          {L.clubHolds ? (
            rival ? <>Next: {display(rival)} {rival.mark} · {Math.round(pct)}%</> : 'Held by the club'
          ) : (
            <>Club: {r.club.mark} · {Math.round(pct)}%</>
          )}
        </span>
      </button>
      {open && (
        <ol className="rb-tile__list">
          {L.top.map((e, i) => (
            <li key={`${e.player}-${e.season ?? ''}`}>
              <span className="rb-rank">{i + 1}</span>
              <span className="rb-val">{e.mark}</span>
              <Name e={e} players={players} onSelect={onSelect} />
              {e.club && <span className="rb-clubtag">Club</span>}
            </li>
          ))}
          {!L.clubHolds && (
            <li className="rb-tile__clubrow">
              <span className="rb-rank">C</span>
              <span className="rb-val">{r.club.mark}</span>
              <Name e={clubEntry} players={players} onSelect={onSelect} />
              <span className="rb-clubtag">Club</span>
            </li>
          )}
        </ol>
      )}
    </li>
  );
};

/** The club's record board next to the league-wide marks, career and season. */
const RecordBoard = ({ players, onSelect }: { players: Player[]; onSelect: (p: Player) => void }) => {
  const [data, setData] = useState<BoardFile | null>(null);
  const [scope, setScope] = useState<'career' | 'season'>('career');
  const [beatenOnly, setBeatenOnly] = useState(false);
  const [open, setOpen] = useState<string | null>(null);
  useEffect(() => {
    let live = true;
    loadBoard().then((d) => live && setData(d));
    return () => {
      live = false;
    };
  }, []);
  const rows = useMemo(() => (data?.records ?? []).filter((r) => r.league), [data]);
  if (!rows.length) return null;
  const broken = rows.filter((r) => r.broken).length;
  const shown = rows.filter((r) => r.scope === scope && (!beatenOnly || r.broken));
  return (
    <section id="record-board" aria-labelledby="record-board-title" className="scroll-mt-20 space-y-3">
      <h2 id="record-board-title" className="section-title text-2xl">
        <BookOpen className="h-5 w-5 text-gold" aria-hidden="true" />
        Record Board
      </h2>
      <SectionIntro id="record-board" takeaway={`${broken} of ${rows.length} club records have been beaten somewhere in the league.`}>
        The game&apos;s record board only counts games played for Skura&apos;s club. Each tile is the best mark across the whole league, in the
        holder&apos;s colours, with the club&apos;s own mark underneath (career cards, and every season since {data?.seasonsFrom ?? 'the first snapshot'} for
        the players tracked then). Tap a tile for the top three.
      </SectionIntro>
      <div className="rb-filters" role="group" aria-label="Record board filters">
        {(['career', 'season'] as const).map((s) => (
          <button key={s} type="button" className={cn('rb-chip', scope === s && 'rb-chip--on')} aria-pressed={scope === s} onClick={() => setScope(s)}>
            {s === 'career' ? 'Career' : 'Season'}
          </button>
        ))}
        <button type="button" className={cn('rb-chip rb-chip--flag', beatenOnly && 'rb-chip--on')} aria-pressed={beatenOnly} onClick={() => setBeatenOnly((b) => !b)}>
          Beaten only
        </button>
      </div>
      {shown.length ? (
        <ul className="rb-grid">
          {shown.map((r) => (
            <Tile key={r.record} r={r} players={players} onSelect={onSelect} open={open === r.record} onToggle={() => setOpen((o) => (o === r.record ? null : r.record))} />
          ))}
        </ul>
      ) : (
        <p className="text-sm text-muted-foreground">None here.</p>
      )}
    </section>
  );
};

export default RecordBoard;
